def drop_redeemed_clients(apps, schema_editor):
    """Redeem tokens are gone, and with them every client a redeem produced: such a
    client lived on a refresh chain its token could restart at will. The clients an
    old mandate provisioned go too: from now on a mandated client logs in with a key.
    Their tokens die with them."""
    Client = apps.get_model("fakts", "Client")
    RedeemToken = apps.get_model("fakts", "RedeemToken")
    OAuth2Token = apps.get_model("authapp", "OAuth2Token")

    redeemed = RedeemToken.objects.filter(client__isnull=False).values("client_id")
    clients = Client.objects.filter(models.Q(pk__in=redeemed) | models.Q(mandate__isnull=False))
    OAuth2Token.objects.filter(client_id__in=clients.values("client_id")).delete()
    clients.delete()


